  if (Array.isArray(value)) {
    return value.length === 0 ? [`${prefix}[]`] : shapeOf(value[0], `${prefix}[]`, depth + 1);
  }

  const names: string[] = [];
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
