  for (const sentence of sentences) {
    const candidate = current + sentence;

    if (count(candidate.trim()) <= limit) {
      current = candidate;
      continue;
    }

    flush();

    if (count(sentence.trim()) <= limit) {
      current = sentence;
      continue;
    }

    let buffer = "";
